package vn.iotstar; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.*; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder; import vn.iotstar.entity.*; import vn.iotstar.repository.*; @SpringBootApplication public class Ex1Application{public static void main(String[]a){SpringApplication.run(Ex1Application.class,a);}@Bean CommandLineRunner init(RoleRepository rr,UserRepository ur,PasswordEncoder pe){return a->{Role user=rr.findByName("ROLE_USER").orElseGet(()->rr.save(Role.builder().name("ROLE_USER").build()));Role admin=rr.findByName("ROLE_ADMIN").orElseGet(()->rr.save(Role.builder().name("ROLE_ADMIN").build()));if(ur.findByUsername("admin01").isEmpty())ur.save(User.builder().username("admin01").email("admin@example.com").password(pe.encode("123456")).fullName("Administrator").enabled(true).role(admin).build());if(ur.findByUsername("user01").isEmpty())ur.save(User.builder().username("user01").email("user01@example.com").password(pe.encode("123456")).fullName("Sinh Viên Demo").enabled(true).role(user).build());};}}